#include <iostream>
#include <vector>
using namespace std;

long long calc(long long num, int length) {
    static vector<long long> p(17, 0);
    if (p[1] == 0) {
        for (int i = 1; i < 17; ++i) {
            p[i] = p[i - 1] * 10 + 1;
        }
    }
    if (length == 0) return 0;
    long long baseVal = p[length];
    long long quotient = num / baseVal;
    long long remainder = num % baseVal;
    long long total = quotient * length;
    if (remainder != 0) {
        long long option1 = calc(remainder, length - 1);
        long long option2 = length + calc(baseVal - remainder, length - 1);
        total += min(option1, option2);
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    long long n;
    cin >> n;
    cout << calc(n, 16) << "\n";
    return 0;
}
